#!/usr/bin/env bash
# End to end (ctest: e2e_gen_input): inputs GENERATED by the build immediately before their consumer compiles
# (kbuild: .tmp_vmlinux0.kallsyms.S written by KSYMS right before AS, zoffset.h before header.S). The client
# is told to start a local compile no earlier than request arrival + racy margin (coordinator.cpp go_local), so such an
# input passes the store rule and the next identical build hits. Writes that land after the compile could read the
# input must still be refused.
#   A  generated just before the compile, same content every build  -> stored on build 1, HIT on build 2
#   B  writer still writing (append) while the compile runs          -> store refused, rebuild correct
#   C  content replaced while the compile runs                        -> store refused, rebuild correct
# On macOS the racy margin defaults to 0.25 s (no coarse-clock resolution to derive it from) and go_local does not
# wait; APFS stamps ctime from the precise clock, so the test sets OPTICC_RACY_S=0.02 there (the largest margin
# go_local waits for; the generator-to-request gap is a few ms, so without the wait case A fails).
set -u
B=${OPTICC_BUILD:-$(cd "$(dirname "$0")/../.." && pwd)/build}
OPTICC=$B/src/opticc/opticc
CC_REAL=${CC_REAL:-$(command -v clang || command -v cc)}   # clang preferred (Ubuntu cc = gcc: external as, other diagnostics)
T=$(mktemp -d /tmp/opticc-e2e-gen.XXXXXX)
fail() { echo "FAIL: $*"; cleanup; exit 1; }
cleanup() { for p in $(lsof -t "$T/c.sock" 2>/dev/null); do kill "$p" 2>/dev/null; done; wait 2>/dev/null; }
trap cleanup EXIT
[ "$(uname)" = Darwin ] && export OPTICC_RACY_S=0.02

cat > "$T/slowcc" <<EOF
#!/bin/sh
"$(command -v "$CC_REAL")" "\$@"; rc=\$?
case " \$* " in *" -c "*) sleep 2;; esac
exit \$rc
EOF
chmod +x "$T/slowcc"

fresh_summary() { local f=$1 pid=$2 m0; m0=$(python3 -c "import os,sys;print(os.stat(sys.argv[1]).st_mtime_ns if os.path.exists(sys.argv[1]) else 0)" "$f")
  kill -USR1 "$pid"; for _ in $(seq 600); do sleep 0.1; [ "$(python3 -c "import os,sys;print(os.stat(sys.argv[1]).st_mtime_ns if os.path.exists(sys.argv[1]) else 0)" "$f")" != "$m0" ] && break; done; sleep 0.1; }
summ() { local p; p=$(lsof -t "$OPTICC_SOCK" 2>/dev/null | head -1); [ -n "$p" ] || { echo 0; return; }
  fresh_summary "$OPTICC_SUMMARY" "$p"; python3 -c "import json;s=json.load(open('$OPTICC_SUMMARY'));print($1)"; }

export OPTICC_SOCK=$T/c.sock OPTICC_TOKEN=e2e OPTICC_POLICY=ect-window OPTICC_MODE=header-push OPTICC_IDLE_TIMEOUT=600
export OPTICC_LOCAL_CACHE=on OPTICC_HOSTS="" OPTICC_SUMMARY=$T/summary.json OPTICC_LOCAL_CACHE_DIR=$T/lc
"$OPTICC" --coordinator > "$T/coord.out" 2> "$T/coord.err" &
for _ in $(seq 600); do [ -S "$OPTICC_SOCK" ] && break; sleep 0.05; done
[ -S "$OPTICC_SOCK" ] || fail "coordinator did not start: $(cat "$T/coord.err")"
mkdir -p "$T/warm"; printf 'int w(void) { return 1; }\n' > "$T/warm/w.c"
( cd "$T/warm" && "$OPTICC" "$CC_REAL" -O2 -c w.c -o w.o ) > /dev/null 2>&1 || fail "warm-up build"
# the first request per compiler waits for its system-include walk (once): warm the slow compiler too, so that
# cases B/C time the write against the compile, not against that walk
( cd "$T/warm" && "$OPTICC" "$T/slowcc" -O2 -c w.c -o w2.o ) > /dev/null 2>&1 || fail "warm-up build (slowcc)"

# A: the header is regenerated (identical bytes) by the rule right before the compile, as kbuild does
mkdir -p "$T/a"
printf 'int t(void);\n#include "gen.h"\nint t(void) { return V; }\n' > "$T/a/t.c"
printf 'all: t.o\nt.o: t.c\n\tprintf "#define V 7\\n" > gen.h\n\t$(CC) -O2 -MD -MF t.o.d -c t.c -o t.o\nclean:\n\trm -f t.o t.o.d gen.h\n' > "$T/a/Makefile"
sleep 0.5
s0=$(summ "s['v4']['racy_store_skips']")
( cd "$T/a" && make -s CC="$OPTICC $CC_REAL" ) > "$T/out.txt" 2>&1 || fail "A: build 1: $(cat "$T/out.txt")"
s1=$(summ "s['v4']['racy_store_skips']")
[ "$s1" = "$s0" ] || fail "A: build 1's store was refused (racy_store_skips $s0 -> $s1): $(summ "s['v4']['skips']")"
h0=$(summ "s['client_fast_hits'] + s['client_cache_hits']")
( cd "$T/a" && make -s clean && make -s CC="$OPTICC $CC_REAL" ) > "$T/out.txt" 2>&1 || fail "A: build 2: $(cat "$T/out.txt")"
h1=$(summ "s['client_fast_hits'] + s['client_cache_hits']")
[ "$h1" -gt "$h0" ] || fail "A: build 2 did not hit (hits $h0 -> $h1): $(summ "s['v4']")"
rm -rf "$T/aref"; cp -r "$T/a" "$T/aref"; ( cd "$T/aref" && make -s clean && make -s CC="$CC_REAL" ) > /dev/null 2>&1 || fail "A: reference"
cmp -s "$T/aref/t.o" "$T/a/t.o" || fail "A: object differs from a plain build"
echo "A: generated-just-before input stored on build 1 and hit on build 2 (hits $h0 -> $h1)"

# B: the generator is still appending while the compile runs (the compile reads "#define V 1", the file ends "100")
mkdir -p "$T/b"
printf '#include "gen.h"\nint t(void) { return V; }\n' > "$T/b/t.c"
s0=$(summ "s['v4']['racy_store_skips']")
( printf '#define V 1' > "$T/b/gen.h"; sleep 1; printf '00\n' >> "$T/b/gen.h" ) &
GPID=$!
sleep 0.2
( cd "$T/b" && "$OPTICC" "$T/slowcc" -O2 -c t.c -o t.o ) > "$T/out.txt" 2>&1 || fail "B: compile: $(cat "$T/out.txt")"
wait "$GPID"
s1=$(summ "s['v4']['racy_store_skips']")
[ "$s1" -gt "$s0" ] || fail "B: the store was not refused (racy_store_skips $s0 -> $s1): $(summ "s['v4']['skips']")"
( cd "$T/b" && rm -f t.o && "$OPTICC" "$CC_REAL" -O2 -c t.c -o t.o ) > /dev/null 2>&1 || fail "B: rebuild"
( cd "$T/b" && "$CC_REAL" -O2 -c t.c -o ref.o ) || fail "B: reference"
cmp -s "$T/b/ref.o" "$T/b/t.o" || fail "B: STALE object after the writer finished"
echo "B: writer in progress at compile start -> store refused, rebuild correct"

# C: the input is replaced (same size, other content) while the compile runs
mkdir -p "$T/c"
printf '#define V 300\n' > "$T/c/gen.h"; printf '#include "gen.h"\nint t(void) { return V; }\n' > "$T/c/t.c"
sleep 0.5
s0=$(summ "s['v4']['racy_store_skips']")
( cd "$T/c" && "$OPTICC" "$T/slowcc" -O2 -c t.c -o t.o ) > "$T/out.txt" 2>&1 & CPID=$!
sleep 1
printf '#define V 400\n' > "$T/c/gen.h"
wait "$CPID" || fail "C: compile: $(cat "$T/out.txt")"
s1=$(summ "s['v4']['racy_store_skips']")
[ "$s1" -gt "$s0" ] || fail "C: the store was not refused (racy_store_skips $s0 -> $s1)"
( cd "$T/c" && rm -f t.o && "$OPTICC" "$CC_REAL" -O2 -c t.c -o t.o ) > /dev/null 2>&1 || fail "C: rebuild"
( cd "$T/c" && "$CC_REAL" -O2 -c t.c -o ref.o ) || fail "C: reference"
cmp -s "$T/c/ref.o" "$T/c/t.o" || fail "C: STALE object after the replacement"
echo "C: content replaced during the compile -> store refused, rebuild correct"

echo "E2E-GEN-INPUT PASS ($T)"
cleanup; trap - EXIT; rm -rf "$T"; exit 0
